def apply_evaluation_data(processed_path=PROCESSED_PATH,rubric_path=RUBRIC_PATH):
 d=json.loads(Path(processed_path).read_text()); pages={x["page"]:x for x in d["chunks"]}; d["schema_version"]="2.1.0"; d["terminology"]=TERMINOLOGY
 if set(pages)!=set(range(1,30)): raise ValueError("Web PDF 1~29쪽이 필요합니다.")
 valid={"cover","table_of_contents","section_divider","core_content","example","supplementary_reference","closing"}
 for p,(_,_,_,r) in P.items(): pages[p].update(page_role=r if r in valid else "core_content",term_ids=[],evidence_units=[],source_issues=[])
 lu={}
 for raw in UNITS:
  z=dict(raw); p=z.pop("page"); pages[p]["term_ids"]=list(dict.fromkeys(pages[p]["term_ids"]+z["term_ids"])); pages[p]["evidence_units"].append(z); lu[z["unit_id"]]=(pages[p],z)
 Path(processed_path).write_text(json.dumps(d,ensure_ascii=False,indent=2)+"\n")
 r=build_rubric(); cs={c["claim_id"]:c for o in r["top_level_objectives"] for s in o["sub_objectives"] for c in s["claims"]}
 if set(cs)!=set(M): raise ValueError(f"Claim mismatch: {set(cs)^set(M)}")
 for cid,uids in M.items():
  tids=[]
  for uid in uids:
   ch,u=lu[uid]; tids+=u["term_ids"]; cs[cid]["evidence"].append({"page":ch["page"],"chunk_id":ch["chunk_id"],"unit_id":uid,"source_excerpt":u["source_excerpt"],"source_status":"verified","review_note":""})
  cs[cid]["term_ids"]=list(dict.fromkeys(tids))
 Path(rubric_path).parent.mkdir(parents=True,exist_ok=True); Path(rubric_path).write_text(json.dumps(r,ensure_ascii=False,indent=2)+"\n")
